    status: 'active',
    objective: 'Expand recorded-snapshot advisor calibration before real API calls.',
    achievementCriteria: Object.freeze([
      'first-call request pack, capture template, and replay harness stay generated by deterministic eval',
      'saved model responses, when captured later, pass strict replay before any live advisor trust',
      'advisor prompt size, JSON validity, skill validity, activation acceptance, rejection behavior, and calibration-tier coverage are reported without API calls by default',
    ]),
